11	pub fn generate_note_id() -> String {
12	    Uuid::now_v7().to_string()
13	}
14	
15	/// Extract the trailing portion of a UUID (after the timestamp segments).
16	pub fn uuid_tail_without_timestamp_prefix(note_id: &str) -> String {
17	    let parts = note_id.split('-').collect::<Vec<_>>();
18	    if parts.len() >= 5 {
19	        return parts[2..].join("-").to_lowercase();
20	    }
21	    note_id.to_lowercase()
22	}
