29	fn utc_note_filename_timestamp(timestamp_ms: i64) -> String {
30	    let seconds = timestamp_ms.div_euclid(1_000);
31	    let millis = timestamp_ms.rem_euclid(1_000);
32	    let nanos = millis.saturating_mul(1_000_000);
33	    let base = OffsetDateTime::from_unix_timestamp(seconds).unwrap_or(OffsetDateTime::UNIX_EPOCH);
34	    let value = base + TimeDuration::nanoseconds(nanos);
35	    value
36	        .format(&format_description!(
37	            "[year]-[month]-[day]T[hour]-[minute]-[second]Z"
38	        ))
