50	/// Derive a short kebab-case slug from the note body for the filename.
51	pub fn slug_from_content(content: &str, fallback: &str) -> String {
52	    const MAX_SLUG_WORDS: usize = 8;
53	    const MAX_SLUG_CHARS: usize = 56;
54	    const MIN_SLUG_CONTENT_CHARS: usize = 8;
55	
56	    let mut normalized = String::with_capacity(content.len().saturating_mul(2));
57	    for ch in content.chars() {
58	        if ch.is_alphanumeric() || ch == '-' || ch == '_' || ch.is_whitespace() {
59	            for lower in ch.to_lowercase() {
60	                normalized.push(lower);
61	            }
62	        } else {
63	            normalized.push(' ');
64	        }
65	    }
66	
67	    let tokens: Vec<&str> = normalized
68	        .split(|ch: char| ch.is_whitespace() || ch == '-' || ch == '_')
69	        .filter(|token| !token.is_empty())
70	        .collect();
71	
72	    let mut words = Vec::new();
73	    let mut index = 0usize;
74	    while index < tokens.len() && words.len() < MAX_SLUG_WORDS {
75	        if index + 3 < tokens.len()
76	            && tokens[index] == "nv"
77	            && tokens[index + 1] == "empty"
78	            && tokens[index + 2] == "line"
79	            && tokens[index + 3] == "token"
80	        {
81	            index += 4;
82	            if index < tokens.len() && is_noise_hash_token(tokens[index]) {
83	                index += 1;
84	            }
85	            continue;
86	        }
87	
88	        let token = tokens[index];
89	        index += 1;
90	        if token.starts_with("http") || token.starts_with("www") {
91	            continue;
92	        }
93	        words.push(token.to_string());
94	    }
95	
96	    let mut slug = if words.is_empty() {
97	        fallback.to_string()
98	    } else {
99	        words.join("-")
100	    };
101	
102	    if slug.chars().count() > MAX_SLUG_CHARS {
103	        slug = slug.chars().take(MAX_SLUG_CHARS).collect();
104	    }
105	
106	    while slug.ends_with('-') {
107	        slug.pop();
108	    }
109	    if slug.is_empty() || slug_content_char_count(&slug) < MIN_SLUG_CONTENT_CHARS {
110	        fallback.to_string()
111	    } else {
112	        slug
113	    }
114	}
115	
116	/// Find an available filename with the given prefix and slug, appending a counter on collision.
117	pub fn allocate_prefixed_note_file_name(
118	    folder: &Path,
119	    prefix: &str,
120	    slug: &str,
121	) -> Result<String, String> {
122	    for attempt in 0..=512usize {
123	        let candidate = if attempt == 0 {
124	            format!("{}-{}.md", prefix, slug)
125	        } else {
126	            format!("{}-{}-{}.md", prefix, slug, attempt)
127	        };
128	        if !folder.join(&candidate).exists() {
129	            return Ok(candidate);
130	        }
131	    }
132	    Err("Failed to allocate note filename.".to_string())
133	}
134	
135	/// Find an available filename using the full UUIDv7 as base name.
136	pub fn allocate_uuid_v7_note_file_name(
137	    folder: &Path,
138	    note_id: &str,
139	) -> Result<String, String> {
140	    let base = note_id.to_lowercase();
141	    for attempt in 0..=512usize {
142	        let candidate = if attempt == 0 {
143	            format!("{}.md", base)
144	        } else {
145	            format!("{}-{}.md", base, attempt)
146	        };
147	        if !folder.join(&candidate).exists() {
148	            return Ok(candidate);
149	        }
150	    }
151	    Err("Failed to allocate note filename.".to_string())
152	}
153	
154	/// Allocate a unique filename for a new note using the chosen format strategy.
155	pub fn allocate_note_file_name(
156	    folder: &Path,
157	    timestamp_ms: i64,
158	    note_id: &str,
159	    content: &str,
160	    fallback_slug: &str,
161	    file_name_format: NoteFileNameFormat,
162	) -> Result<String, String> {
163	    match file_name_format {
164	        NoteFileNameFormat::UtcTimestampSlug => {
165	            let prefix = utc_note_filename_timestamp(timestamp_ms);
166	            let slug = slug_from_content(content, fallback_slug);
167	            allocate_prefixed_note_file_name(folder, &prefix, &slug)
168	        }
169	        NoteFileNameFormat::UuidV7 => allocate_uuid_v7_note_file_name(folder, note_id),
170	        NoteFileNameFormat::UuidV7PrefixSlug => {
171	            let prefix = uuid_prefix_with_timestamp(note_id);
172	            let slug = slug_from_content(content, fallback_slug);
173	            allocate_prefixed_note_file_name(folder, &prefix, &slug)
174	        }
175	    }
176	}
