190	        // Cyrillic letters are alphanumeric and must survive slugging.
191	        assert_eq!(
192	            slug_from_content("Привет мир друзья", "fallback"),
193	            "привет-мир-друзья"
194	        );
195	    }
196	
197	    #[test]
198	    fn slug_from_content_falls_back_when_too_short() {
199	        // "hi" is below the minimum content-char threshold, so the fallback wins.
200	        assert_eq!(slug_from_content("Hi", "2024-note"), "2024-note");
201	    }
202	
203	    #[test]
204	    fn slug_from_content_strips_empty_line_token_noise() {
205	        // The NV_EMPTY_LINE_TOKEN marker and its trailing hash are dropped.
206	        assert_eq!(
207	            slug_from_content("nv empty line token a1b2c3d4 hello world friend", "fb"),
208	            "hello-world-friend"
209	        );
210	    }
211	
212	    #[test]
213	    fn slug_from_content_truncates_to_max_chars() {
214	        let slug = slug_from_content(&"a".repeat(100), "fb");
215	        assert_eq!(slug.chars().count(), 56);
216	    }
