220	        assert_eq!(note_parent_folder_path("Feed/note.md"), "Feed");
221	        assert_eq!(note_parent_folder_path("a/b/c.md"), "a/b");
222	        assert_eq!(note_parent_folder_path("note.md"), "");
223	    }
224	}
