1	//! Front-matter: parse and render the YAML-ish header stored on each note.
2	
3	use std::{fs, path::Path};
4	
5	use crate::encrypt_note_body_for_write;
6	
7	use super::NoteFrontMatter;
8	
9	/// Parse `---` delimited YAML-ish front-matter from a raw markdown string.
10	pub fn parse_note_front_matter(raw: &str) -> (NoteFrontMatter, String) {
11	    let mut meta = NoteFrontMatter::default();
12	    let normalized = raw.replace("\r\n", "\n");
13	    if !normalized.starts_with("---\n") {
14	        return (meta, raw.to_string());
15	    }
16	    let Some(close_marker_index) = normalized[4..].find("\n---\n") else {
17	        return (meta, raw.to_string());
18	    };
19	    let header_end = 4 + close_marker_index;
20	    let header = &normalized[4..header_end];
21	    let body = &normalized[(header_end + 5)..];
22	
23	    for line in header.lines() {
24	        let trimmed = line.trim();
25	        if trimmed.is_empty() {
26	            continue;
27	        }
28	        let Some((key_raw, value_raw)) = trimmed.split_once(':') else {
29	            meta.passthrough_lines.push(trimmed.to_string());
30	            continue;
31	        };
32	        let key = key_raw.trim().to_lowercase();
33	        let value = value_raw
34	            .trim()
35	            .trim_matches('"')
36	            .trim_matches('\'')
37	            .to_string();
38	        match key.as_str() {
39	            "id" => {
40	                if !value.is_empty() {
41	                    meta.id = Some(value);
42	                }
43	            }
44	            "created_ms" => {
45	                if let Ok(parsed) = value.parse::<i64>() {
46	                    meta.created_ms = Some(parsed);
47	                } else {
48	                    meta.passthrough_lines.push(trimmed.to_string());
49	                }
50	            }
51	            "updated_ms" => {
52	                if let Ok(parsed) = value.parse::<i64>() {
53	                    meta.updated_ms = Some(parsed);
54	                } else {
55	                    meta.passthrough_lines.push(trimmed.to_string());
56	                }
57	            }
58	            "type" => {
59	                if !value.is_empty() {
60	                    meta.note_type = Some(value);
61	                }
62	            }
63	            "archived_ms" => {
64	                if let Ok(parsed) = value.parse::<i64>() {
65	                    meta.archived_ms = Some(parsed);
66	                } else {
67	                    meta.passthrough_lines.push(trimmed.to_string());
68	                }
69	            }
70	            "reviewed_ms" => {
71	                if let Ok(parsed) = value.parse::<i64>() {
72	                    meta.reviewed_ms = Some(parsed);
73	                } else {
74	                    meta.passthrough_lines.push(trimmed.to_string());
75	                }
76	            }
77	            "recording_audio_path" => {
78	                if !value.is_empty() {
79	                    meta.recording_audio_path = Some(value);
80	                }
81	            }
82	            "handwriting_attachment_path" => {
83	                if !value.is_empty() {
84	                    meta.handwriting_attachment_path = Some(value);
85	                }
86	            }
87	            "transcription_status" => {
88	                if !value.is_empty() {
89	                    meta.transcription_status = Some(value);
90	                }
91	            }
92	            "transcription_error" => {
93	                if !value.is_empty() {
94	                    meta.transcription_error = Some(value);
95	                }
96	            }
97	            "transcription_updated_ms" => {
98	                if let Ok(parsed) = value.parse::<i64>() {
99	                    meta.transcription_updated_ms = Some(parsed);
100	                } else {
101	                    meta.passthrough_lines.push(trimmed.to_string());
102	                }
103	            }
104	            "transcription_id" => {
105	                if !value.is_empty() {
106	                    meta.transcription_id = Some(value);
107	                }
108	            }
109	            "ocr_status" => {
110	                if !value.is_empty() {
111	                    meta.ocr_status = Some(value);
112	                }
113	            }
114	            "ocr_error" => {
115	                if !value.is_empty() {
116	                    meta.ocr_error = Some(value);
117	                }
118	            }
119	            "ocr_updated_ms" => {
120	                if let Ok(parsed) = value.parse::<i64>() {
121	                    meta.ocr_updated_ms = Some(parsed);
122	                } else {
123	                    meta.passthrough_lines.push(trimmed.to_string());
124	                }
125	            }
126	            _ => meta.passthrough_lines.push(trimmed.to_string()),
127	        }
128	    }
129	
130	    (meta, body.to_string())
131	}
132	
133	/// Escape a front-matter value if it contains special characters.
134	fn front_matter_safe_value(value: &str) -> String {
135	    if value
136	        .chars()
137	        .all(|char| char.is_ascii_alphanumeric() || matches!(char, '-' | '_' | '.'))
138	    {
139	        value.to_string()
140	    } else {
141	        format!("{:?}", value)
142	    }
143	}
144	
145	/// Serialize front-matter + body back into a markdown string.
146	pub fn render_note_with_front_matter(meta: &NoteFrontMatter, body: &str) -> String {
147	    let mut output = String::new();
148	    output.push_str("---\n");
149	    if let Some(id) = &meta.id {
150	        output.push_str(&format!("id: {}\n", front_matter_safe_value(id)));
151	    }
152	    if let Some(created_ms) = meta.created_ms {
153	        output.push_str(&format!("created_ms: {}\n", created_ms));
154	    }
155	    if let Some(updated_ms) = meta.updated_ms {
156	        output.push_str(&format!("updated_ms: {}\n", updated_ms));
157	    }
158	    if let Some(note_type) = &meta.note_type {
159	        output.push_str(&format!("type: {}\n", front_matter_safe_value(note_type)));
160	    }
161	    if let Some(archived_ms) = meta.archived_ms {
162	        output.push_str(&format!("archived_ms: {}\n", archived_ms));
163	    }
164	    if let Some(reviewed_ms) = meta.reviewed_ms {
165	        output.push_str(&format!("reviewed_ms: {}\n", reviewed_ms));
166	    }
167	    if let Some(audio_path) = &meta.recording_audio_path {
168	        output.push_str(&format!(
169	            "recording_audio_path: {}\n",
170	            front_matter_safe_value(audio_path)
171	        ));
172	    }
173	    if let Some(attachment_path) = &meta.handwriting_attachment_path {
174	        output.push_str(&format!(
175	            "handwriting_attachment_path: {}\n",
176	            front_matter_safe_value(attachment_path)
177	        ));
178	    }
179	    if let Some(status) = &meta.transcription_status {
180	        output.push_str(&format!(
181	            "transcription_status: {}\n",
182	            front_matter_safe_value(status)
183	        ));
184	    }
185	    if let Some(error) = &meta.transcription_error {
186	        output.push_str(&format!(
187	            "transcription_error: {}\n",
188	            front_matter_safe_value(error)
189	        ));
190	    }
191	    if let Some(updated_ms) = meta.transcription_updated_ms {
192	        output.push_str(&format!("transcription_updated_ms: {}\n", updated_ms));
193	    }
194	    if let Some(transcription_id) = &meta.transcription_id {
195	        output.push_str(&format!(
196	            "transcription_id: {}\n",
