283	        let app_data = crate::app_data_dir(&self.app)?;
284	        let app_config = crate::load_app_config(&app_data);
285	
286	        let api_key = args
287	            .assembly_api_key
288	            .as_deref()
289	            .filter(|s| !s.is_empty())
290	            .unwrap_or(app_config.assemblyai_api_key.as_str())
291	            .trim();
292	
293	        if api_key.is_empty() {
294	            return Err("AssemblyAI API key is required.".to_string());
