582	/// Update a recording note's transcription status and body on disk.
583	pub fn update_recording_note_status(
584	    note_path: &Path,
585	    status: &str,
586	    error: Option<String>,
587	    transcript_id: Option<String>,
588	    transcript_text: Option<&str>,
589	) -> Result<(), String> {
590	    let raw = fs::read_to_string(note_path).map_err(|issue| issue.to_string())?;
591	    let (mut meta, _) = parse_note_front_matter(&raw);
592	    if meta.id.is_none() {
593	        meta.id = Some(generate_note_id());
594	    }
595	    let now = now_ms();
596	    if meta.created_ms.is_none() {
597	        meta.created_ms = now;
598	    }
599	    meta.updated_ms = now.or(meta.updated_ms);
600	    meta.note_type = Some(RECORDING_FRONTMATTER_TYPE.to_string());
601	    meta.transcription_status = Some(status.to_string());
602	    meta.transcription_error = error.clone();
603	    meta.transcription_updated_ms = now.or(meta.transcription_updated_ms);
604	    meta.transcription_id = transcript_id;
605	    let next_body = recording_note_body(status, transcript_text);
606	    write_note_with_front_matter(note_path, &meta, &next_body)
607	}
