917	    folder: &Path,
918	    timestamp_ms: i64,
919	    note_id: &str,
920	    file_name_format: NoteFileNameFormat,
921	) -> Result<String, String> {
922	    let fallback = format!("recording-{}", uuid_tail_without_timestamp_prefix(note_id));
923	    allocate_note_file_name(
924	        folder,
925	        timestamp_ms,
926	        note_id,
927	        "",
928	        &fallback,
929	        file_name_format,
930	    )
931	}
932	
933	/// Allocate a unique audio file path inside the Recordings storage folder.
934	pub fn recording_audio_file_path(root: &Path, extension: &str) -> Result<PathBuf, String> {
935	    let storage = recording_storage_root(root);
936	    fs::create_dir_all(&storage).map_err(|error| error.to_string())?;
937	    for _ in 0..=512usize {
938	        let candidate = storage.join(format!(
939	            "{}-{}.{}",
940	            AUDIO_FILE_NAME_PREFIX,
941	            Uuid::now_v7(),
942	            extension
943	        ));
944	        if !candidate.exists() {
945	            return Ok(candidate);
946	        }
947	    }
948	    Err("Failed to allocate recording audio filename.".to_string())
949	}
950	
951	/// Resolve the target folder for a new recording, falling back to Feed.
952	pub fn resolve_recording_target_folder(
953	    app: &AppEnv,
954	    requested: Option<&str>,
955	) -> Result<(String, PathBuf), String> {
956	    let root = notes_root(app)?;
957	    let candidate = requested.unwrap_or("").trim();
958	    if !candidate.is_empty() {
959	        let path = resolve_path(app, candidate)?;
960	        if path.exists() && path.is_dir() && !is_storage_folder_path(&root, &path) {
961	            return Ok((strip_root(&root, &path), path));
962	        }
963	    }
964	    let fallback = root.join(FEED_FOLDER);
965	    Ok((FEED_FOLDER.to_string(), fallback))
966	}
