1	//! Apple Notes import.
2	//!
3	//! Imports an *exported* Apple Notes folder tree into the active profile's notes
4	//! root. Apple Notes has no native bulk export, so users export with a tool such
5	//! as the free "Exporter" app, which produces a nested folder of Markdown (and
6	//! sometimes HTML / plain-text) files. This adapter walks that tree and creates
7	//! app notes, preserving each note's original creation date.
8	//!
9	//! Two modes:
10	//!   * `preserve` — recreate the source folder hierarchy under a single target
11	//!                  folder in the notes root.
12	//!   * `flatten`  — drop every note directly into `Feed`, discarding hierarchy.
13	//!
14	//! Creation dates come from YAML front-matter (`created` / `date` / `created_ms`
15	//! …) when present, otherwise the source file's filesystem timestamps.
16	//!
17	//! Progress is exposed via a process-global snapshot that the frontend polls —
18	//! matching the recordings/handwriting queue pattern (the app uses no Tauri
19	//! events). The actual work runs on a detached worker thread spawned by the
20	//! command layer; only the resolved notes root + args cross the boundary, so the
21	//! worker never touches the `AppHandle`. Body encryption still works because
22	//! `write_note_with_front_matter` reads the unlocked key from the global
23	//! security runtime.
24	
25	use crate::AppEnv;
26	use crate::ports::import::ImportGateway;
27	use crate::*;
28	use serde::{Deserialize, Serialize};
29	use std::path::Path;
30	use std::sync::{Mutex, OnceLock};
31	use time::format_description::well_known::Rfc3339;
32	use time::macros::format_description;
33	use time::{Date, OffsetDateTime, PrimitiveDateTime};
34	
35	/// File extensions we treat as importable note text.
36	const TEXT_EXTENSIONS: &[&str] = &["md", "markdown", "txt", "text", "html", "htm"];
37	/// Front-matter keys that may carry the original creation date, in priority order.
38	const CREATED_KEYS: &[&str] = &[
39	    "created_ms",
40	    "created",
41	    "creationdate",
42	    "created_at",
43	    "date",
44	    "created-date",
45	];
46	/// Cap on per-note errors retained for the UI so a pathological import can't grow
47	/// the snapshot without bound.
48	const MAX_TRACKED_ERRORS: usize = 25;
49	/// Default target folder when preserving structure and no name is supplied.
50	const DEFAULT_IMPORT_FOLDER: &str = "Imported Notes";
51	
52	/// Core import gateway. Resolving the active profile and spawning the
53	/// worker are adapter concerns because both depend on process/runtime state.
54	pub struct ImportAdapter {
55	    app: AppEnv,
56	}
57	
58	impl ImportAdapter {
59	    pub fn new(app: AppEnv) -> Self {
60	        Self { app }
61	    }
62	}
63	
64	impl ImportGateway for ImportAdapter {
65	    type Scan = AppleImportScan;
66	    type Args = AppleImportArgs;
67	    type State = AppleImportState;
68	
69	    fn scan(&self, path: &str) -> Result<Self::Scan, String> {
70	        scan_apple_import_source(Path::new(path.trim()))
71	    }
72	
73	    fn start(&self, args: Self::Args) -> Result<(), String> {
74	        let notes_root = ensured_notes_root(&self.app)?;
75	        let target_label = match args.mode {
76	            AppleImportMode::Flatten => "Feed".to_string(),
77	            AppleImportMode::Preserve => args
78	                .target_folder
79	                .as_deref()
80	                .map(str::trim)
81	                .filter(|value| !value.is_empty())
82	                .map(str::to_string)
83	                .unwrap_or_else(|| "Imported Notes".to_string()),
84	        };
85	        begin_apple_import(target_label)?;
86	        std::thread::spawn(move || run_apple_notes_import(notes_root, args));
87	        Ok(())
88	    }
89	
90	    fn status(&self) -> Result<Self::State, String> {
91	        Ok(apple_import_snapshot())
92	    }
93	}
