95	// ── DTOs ─────────────────────────────────────────────────────────────────────
96	
97	/// Preview of an export folder, returned before the import runs.
98	#[derive(Clone, Serialize)]
99	pub struct AppleImportScan {
100	    /// Number of importable note files found (recursive).
101	    pub note_count: u32,
102	    /// Number of distinct sub-folders that contain notes.
103	    pub folder_count: u32,
104	    /// Non-text files skipped (attachments, images, …).
105	    pub skipped_files: u32,
106	    /// Base name of the chosen folder — the default target-folder suggestion.
107	    pub source_name: String,
108	    /// A handful of note titles, so the UI can show what will be imported.
109	    pub sample_titles: Vec<String>,
110	}
111	
112	/// Whether to mirror the source hierarchy or collapse everything into Feed.
113	#[derive(Clone, Copy, Deserialize, PartialEq, Eq)]
114	#[serde(rename_all = "snake_case")]
115	pub enum AppleImportMode {
116	    Preserve,
117	    Flatten,
118	}
119	
120	/// Arguments for an import run.
121	#[derive(Deserialize)]
122	pub struct AppleImportArgs {
123	    pub source_path: String,
124	    pub mode: AppleImportMode,
125	    /// Target folder name for `preserve` mode. Defaults to the source base name.
126	    #[serde(default)]
127	    pub target_folder: Option<String>,
128	    /// New-note filename strategy (mirrors the active profile setting).
129	    #[serde(default)]
130	    pub file_name_format: NoteFileNameFormat,
131	}
132	
133	/// Live, pollable progress for the current/last import.
134	#[derive(Clone, Default, Serialize)]
135	pub struct AppleImportState {
136	    pub running: bool,
137	    pub done: bool,
138	    pub total: u32,
139	    pub processed: u32,
140	    pub imported: u32,
141	    pub skipped: u32,
142	    pub failed: u32,
143	    pub folders_created: u32,
144	    /// Title of the note currently being written.
145	    pub current: String,
146	    /// Resolved destination folder (for the UI summary).
147	    pub target_folder: String,
148	    /// Fatal error that aborted the whole run, if any.
149	    pub error: Option<String>,
150	    /// Sample of per-note failures (capped at `MAX_TRACKED_ERRORS`).
151	    pub errors: Vec<String>,
152	}
153	
154	// ── Progress state ─────────────────────────────────────────────────────────────
155	
156	fn import_state() -> &'static Mutex<AppleImportState> {
157	    static STATE: OnceLock<Mutex<AppleImportState>> = OnceLock::new();
158	    STATE.get_or_init(|| Mutex::new(AppleImportState::default()))
159	}
160	
161	/// Snapshot the current progress for the polling UI.
162	pub fn apple_import_snapshot() -> AppleImportState {
163	    import_state()
164	        .lock()
165	        .map(|state| state.clone())
166	        .unwrap_or_default()
167	}
168	
169	/// Claim the single import slot, resetting progress. Errors if one is running.
170	pub fn begin_apple_import(target_folder: String) -> Result<(), String> {
171	    let mut state = import_state()
172	        .lock()
173	        .map_err(|_| "Import state is unavailable.".to_string())?;
174	    if state.running {
175	        return Err("An import is already running.".to_string());
176	    }
177	    *state = AppleImportState {
178	        running: true,
179	        target_folder,
180	        ..Default::default()
181	    };
182	    Ok(())
183	}
184	
185	/// Mutate the shared progress state, ignoring lock poisoning.
186	fn with_state(update: impl FnOnce(&mut AppleImportState)) {
187	    if let Ok(mut state) = import_state().lock() {
188	        update(&mut state);
189	    }
190	}
191	
192	// ── Source scanning ──────────────────────────────────────────────────────────
193	
194	/// A single importable file plus its POSIX-style directory relative to the root.
195	struct ImportFile {
196	    path: PathBuf,
197	    rel_dir: String,
198	}
199	
200	/// Produce a preview of what an export folder contains.
201	pub fn scan_apple_import_source(source: &Path) -> Result<AppleImportScan, String> {
202	    if !source.exists() || !source.is_dir() {
203	        return Err("The selected path is not a folder.".to_string());
204	    }
205	    let (files, skipped) = collect_import_files(source);
206	    let mut folders: HashSet<String> = HashSet::new();
207	    for file in &files {
208	        if !file.rel_dir.is_empty() {
209	            folders.insert(file.rel_dir.clone());
210	        }
211	    }
212	    let sample_titles = files
213	        .iter()
214	        .take(6)
215	        .map(|file| title_from_path(&file.path))
216	        .collect();
217	    Ok(AppleImportScan {
218	        note_count: files.len() as u32,
219	        folder_count: folders.len() as u32,
220	        skipped_files: skipped,
221	        source_name: source
222	            .file_name()
223	            .map(|name| name.to_string_lossy().to_string())
224	            .filter(|name| !name.is_empty())
225	            .unwrap_or_else(|| DEFAULT_IMPORT_FOLDER.to_string()),
226	        sample_titles,
227	    })
228	}
229	
230	/// Walk the source tree, returning importable files and the count of files
231	/// skipped because they are not note text (attachments, images, …).
232	fn collect_import_files(source: &Path) -> (Vec<ImportFile>, u32) {
233	    let mut files = Vec::new();
234	    let mut skipped = 0u32;
235	    walk_dir(source, "", &mut files, &mut skipped);
236	    (files, skipped)
237	}
238	
239	fn walk_dir(dir: &Path, rel: &str, files: &mut Vec<ImportFile>, skipped: &mut u32) {
240	    let Ok(entries) = fs::read_dir(dir) else {
241	        return;
242	    };
243	    for entry in entries.flatten() {
244	        let name = entry.file_name().to_string_lossy().to_string();
245	        // Skip dotfiles (.DS_Store, .git, …) and the app's own order metadata.
246	        if name.starts_with('.') {
247	            continue;
248	        }
249	        let Ok(file_type) = entry.file_type() else {
250	            continue;
251	        };
252	        let path = entry.path();
253	        if file_type.is_dir() {
254	            let child_rel = if rel.is_empty() {
255	                name
256	            } else {
257	                format!("{}/{}", rel, name)
258	            };
259	            walk_dir(&path, &child_rel, files, skipped);
260	        } else if file_type.is_file() {
261	            if has_text_extension(&path) {
262	                files.push(ImportFile {
263	                    path,
264	                    rel_dir: rel.to_string(),
265	                });
266	            } else {
267	                *skipped += 1;
268	            }
269	        }
270	    }
271	}
272	
273	fn has_text_extension(path: &Path) -> bool {
274	    extension_lower(path)
275	        .map(|ext| TEXT_EXTENSIONS.contains(&ext.as_str()))
276	        .unwrap_or(false)
277	}
278	
279	fn extension_lower(path: &Path) -> Option<String> {
280	    path.extension()
281	        .map(|ext| ext.to_string_lossy().to_ascii_lowercase())
282	}
283	
284	/// A human-ish title for progress/preview: the file stem.
285	fn title_from_path(path: &Path) -> String {
286	    path.file_stem()
287	        .map(|stem| stem.to_string_lossy().to_string())
288	        .unwrap_or_else(|| "Untitled".to_string())
289	}
290	
291	// ── Import worker ──────────────────────────────────────────────────────────────
292	
293	/// Per-note outcome.
294	enum Imported {
295	    Created,
296	}
297	
298	/// Run the import to completion, then mark the shared state finished. Spawned on
299	/// a detached worker thread by the command layer.
300	pub fn run_apple_notes_import(notes_root: PathBuf, args: AppleImportArgs) {
301	    let result = import_inner(&notes_root, &args);
302	    with_state(|state| {
303	        state.running = false;
304	        state.done = true;
305	        if let Err(err) = result {
306	            state.error = Some(err);
307	        }
308	    });
309	}
310	
311	fn import_inner(notes_root: &Path, args: &AppleImportArgs) -> Result<(), String> {
312	    let source = PathBuf::from(args.source_path.trim());
313	    if !source.is_dir() {
314	        return Err("The selected source folder no longer exists.".to_string());
315	    }
316	
317	    let base_target = match args.mode {
318	        AppleImportMode::Flatten => FEED_FOLDER.to_string(),
319	        AppleImportMode::Preserve => resolve_preserve_target(&source, args),
320	    };
321	
322	    // Reject a target that resolves into hidden storage (Recordings/attachments).
323	    if is_storage_folder_path(notes_root, &join_rel(notes_root, &base_target)) {
324	        return Err("Choose a different target folder — that name is reserved.".to_string());
325	    }
326	    with_state(|state| state.target_folder = base_target.clone());
327	
328	    let (files, _skipped) = collect_import_files(&source);
329	    with_state(|state| state.total = files.len() as u32);
330	
331	    let mut created_folders: HashSet<String> = HashSet::new();
332	    for file in &files {
333	        with_state(|state| state.current = title_from_path(&file.path));
334	        let outcome = import_one(notes_root, &base_target, args, file, &mut created_folders);
335	        with_state(|state| {
336	            state.processed += 1;
337	            match outcome {
338	                Ok(Imported::Created) => state.imported += 1,
339	                Err(ref err) => {
340	                    state.failed += 1;
341	                    if state.errors.len() < MAX_TRACKED_ERRORS {
342	                        state
343	                            .errors
344	                            .push(format!("{}: {}", title_from_path(&file.path), err));
345	                    }
346	                }
347	            }
348	            state.folders_created = created_folders.len() as u32;
349	        });
350	    }
351	    Ok(())
352	}
353	
354	fn import_one(
355	    notes_root: &Path,
356	    base_target: &str,
357	    args: &AppleImportArgs,
358	    file: &ImportFile,
359	    created_folders: &mut HashSet<String>,
360	) -> Result<Imported, String> {
361	    let parsed = read_and_parse_note(file)?;
362	
363	    let folder_rel = match args.mode {
364	        AppleImportMode::Flatten => FEED_FOLDER.to_string(),
365	        AppleImportMode::Preserve => {
366	            let sub = sanitize_rel_path(&file.rel_dir);
367	            if sub.is_empty() {
368	                base_target.to_string()
369	            } else {
370	                format!("{}/{}", base_target, sub)
371	            }
372	        }
373	    };
374	
375	    let folder_full = join_rel(notes_root, &folder_rel);
376	    if is_storage_folder_path(notes_root, &folder_full) {
377	        return Err("Destination resolves to reserved storage.".to_string());
378	    }
379	    fs::create_dir_all(&folder_full).map_err(|err| err.to_string())?;
380	    created_folders.insert(folder_rel);
381	
382	    let note_id = generate_note_id();
383	    let file_name = allocate_note_file_name(
384	        &folder_full,
385	        parsed.created_ms,
386	        &note_id,
387	        &parsed.body,
388	        "imported-note",
389	        args.file_name_format,
390	    )?;
391	    let path = folder_full.join(&file_name);
392	
393	    let meta = NoteFrontMatter {
394	        id: Some(note_id),
395	        created_ms: Some(parsed.created_ms),
396	        updated_ms: Some(parsed.created_ms),
397	        ..Default::default()
398	    };
399	    write_note_with_front_matter(&path, &meta, &parsed.body)?;
400	    if !is_feed_folder_path(notes_root, &folder_full) {
401	        update_order_append(&folder_full, std::slice::from_ref(&file_name), false)?;
402	    }
403	    Ok(Imported::Created)
404	}
405	
406	/// Resolve + sanitize the single top-level folder for `preserve` mode.
407	fn resolve_preserve_target(source: &Path, args: &AppleImportArgs) -> String {
408	    let requested = args
409	        .target_folder
410	        .as_deref()
411	        .map(str::trim)
412	        .filter(|value| !value.is_empty())
413	        .map(sanitize_segment)
414	        .filter(|value| !value.is_empty());
415	    requested
416	        .or_else(|| {
417	            source
418	                .file_name()
419	                .map(|name| sanitize_segment(&name.to_string_lossy()))
420	                .filter(|value| !value.is_empty())
421	        })
422	        .unwrap_or_else(|| DEFAULT_IMPORT_FOLDER.to_string())
423	}
424	
425	/// Join a POSIX-style relative path onto a root using native separators.
426	fn join_rel(root: &Path, rel: &str) -> PathBuf {
427	    let mut path = root.to_path_buf();
428	    for segment in rel.split('/') {
429	        if !segment.is_empty() {
430	            path.push(segment);
431	        }
432	    }
433	    path
434	}
435	
436	/// Strip characters that are illegal/awkward in folder names; returns "" if the
437	/// whole segment is unusable.
438	fn sanitize_segment(name: &str) -> String {
439	    let cleaned: String = name
440	        .chars()
441	        .map(|ch| match ch {
442	            '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|' => ' ',
443	            ch if ch.is_control() => ' ',
444	            ch => ch,
445	        })
446	        .collect();
447	    let trimmed = cleaned.trim().trim_matches('.').trim();
448	    if trimmed == "." || trimmed == ".." {
449	        return String::new();
450	    }
451	    trimmed.to_string()
452	}
453	
454	/// Sanitize each segment of a relative directory, dropping empties.
455	fn sanitize_rel_path(rel: &str) -> String {
456	    rel.split('/')
457	        .map(sanitize_segment)
458	        .filter(|segment| !segment.is_empty())
459	        .collect::<Vec<_>>()
460	        .join("/")
461	}
462	
463	// ── Note parsing ─────────────────────────────────────────────────────────────
464	
465	struct ParsedNote {
466	    body: String,
467	    created_ms: i64,
468	}
469	
470	fn read_and_parse_note(file: &ImportFile) -> Result<ParsedNote, String> {
471	    let raw = fs::read_to_string(&file.path).map_err(|err| err.to_string())?;
472	    let is_html = matches!(extension_lower(&file.path).as_deref(), Some("html" | "htm"));
473	
474	    let (front_matter_date, body) = if is_html {
475	        (None, html_to_markdown(&raw))
476	    } else {
477	        let (date, stripped) = split_front_matter(&raw);
478	        (date, stripped)
479	    };
480	
481	    let created_ms = front_matter_date
482	        .or_else(|| file_created_ms(&file.path))
483	        .or_else(now_ms)
484	        .unwrap_or(0);
485	
486	    // Keep the title in-body (Apple Notes keeps the title as the first line). If
487	    // the note is empty, fall back to the filename so it survives as a titled note.
488	    let body = if body.trim().is_empty() {
489	        title_from_path(&file.path)
490	    } else {
491	        body
492	    };
493	
494	    Ok(ParsedNote { body, created_ms })
495	}
496	
497	/// Split a leading YAML front-matter block (if any) from the body, extracting the
498	/// best creation date. Foreign front-matter is always removed so it never leaks
499	/// into the imported note body.
500	fn split_front_matter(raw: &str) -> (Option<i64>, String) {
501	    let normalized = raw.strip_prefix('\u{feff}').unwrap_or(raw);
502	    let mut lines = normalized.lines();
503	    if lines.next().map(str::trim) != Some("---") {
504	        return (None, normalized.to_string());
505	    }
506	
507	    let mut fields: HashMap<String, String> = HashMap::new();
508	    let mut closed = false;
509	    // Track byte offsets as we go (`lines()` drops separators, so we re-walk
510	    // with `split_inclusive` from just past the opening fence). When we hit the
511	    // closing fence, `offset` already points at the start of the body.
512	    let body_scan_start = normalized
513	        .find('\n')
514	        .map(|idx| idx + 1)
515	        .unwrap_or(normalized.len());
516	    let mut offset = body_scan_start;
517	    for line in normalized[body_scan_start..].split_inclusive('\n') {
518	        let trimmed = line.trim_end_matches(['\n', '\r']);
519	        offset += line.len();
520	        if trimmed.trim() == "---" {
521	            closed = true;
522	            break;
523	        }
524	        if let Some((key, value)) = trimmed.split_once(':') {
525	            fields.insert(key.trim().to_ascii_lowercase(), value.trim().to_string());
526	        }
527	    }
528	
529	    if !closed {
530	        // No closing fence — treat the whole thing as body (a lone "---" line).
531	        return (None, normalized.to_string());
532	    }
533	
534	    let date = CREATED_KEYS
535	        .iter()
536	        .find_map(|key| fields.get(*key))
537	        .and_then(|value| parse_date_value(value));
538	    let body = normalized[offset..]
539	        .trim_start_matches(['\n', '\r'])
540	        .to_string();
541	    (date, body)
542	}
543	
544	/// Parse a front-matter date value into epoch milliseconds.
545	fn parse_date_value(value: &str) -> Option<i64> {
546	    let v = value.trim().trim_matches(|c| c == '"' || c == '\'').trim();
547	    if v.is_empty() {
548	        return None;
549	    }
550	    // Bare epoch number: milliseconds if large, otherwise seconds.
551	    if let Ok(num) = v.parse::<i64>() {
552	        return Some(if num >= 1_000_000_000_000 {
553	            num
554	        } else {
555	            num.saturating_mul(1000)
556	        });
557	    }
558	    // RFC 3339 / ISO 8601 with timezone.
559	    if let Ok(dt) = OffsetDateTime::parse(v, &Rfc3339) {
560	        return i64::try_from(dt.unix_timestamp_nanos() / 1_000_000).ok();
561	    }
562	    // "YYYY-MM-DD HH:MM:SS" (assume UTC).
563	    let datetime_fmt = format_description!("[year]-[month]-[day] [hour]:[minute]:[second]");
564	    if let Ok(dt) = PrimitiveDateTime::parse(v, &datetime_fmt) {
565	        return Some(dt.assume_utc().unix_timestamp().saturating_mul(1000));
566	    }
567	    // Date only.
568	    let date_fmt = format_description!("[year]-[month]-[day]");
569	    if let Ok(date) = Date::parse(v, &date_fmt) {
570	        return Some(
571	            date.midnight()
572	                .assume_utc()
573	                .unix_timestamp()
574	                .saturating_mul(1000),
575	        );
576	    }
577	    None
578	}
579	
580	/// Filesystem creation time (or modified, if birthtime is unavailable) in ms.
581	fn file_created_ms(path: &Path) -> Option<i64> {
582	    let meta = fs::metadata(path).ok()?;
583	    let time = meta.created().or_else(|_| meta.modified()).ok()?;
584	    time_to_ms(time)
585	}
586	
587	// ── HTML → Markdown ──────────────────────────────────────────────────────────
588	
589	/// Best-effort HTML → Markdown for Apple Notes exports. Apple Notes HTML is
590	/// simple and regular (headings, paragraphs, `<div>`/`<br>` breaks, bold/italic,
591	/// lists, links), so a focused converter avoids pulling in a full HTML crate.
592	fn html_to_markdown(html: &str) -> String {
593	    let without_meta = strip_blocks(html, &["head", "style", "script"]);
594	    let with_links = rewrite_anchors(&without_meta);
595	
596	    let bytes = with_links.as_bytes();
597	    let mut out = String::with_capacity(with_links.len());
598	    let mut i = 0usize;
599	    while i < bytes.len() {
600	        if bytes[i] == b'<' {
601	            // Read to the closing '>'.
602	            let Some(end_rel) = with_links[i..].find('>') else {
603	                break;
604	            };
605	            let tag = &with_links[i + 1..i + end_rel];
606	            out.push_str(&render_tag(tag));
607	            i += end_rel + 1;
608	        } else {
609	            out.push(bytes[i] as char);
610	            i += 1;
611	        }
612	    }
613	
614	    let decoded = decode_entities(&out);
615	    collapse_whitespace(&decoded)
616	}
617	
618	/// Translate a single tag (contents between `<` and `>`) into Markdown glue.
619	fn render_tag(tag: &str) -> String {
620	    let trimmed = tag.trim();
621	    let is_close = trimmed.starts_with('/');
622	    let name: String = trimmed
623	        .trim_start_matches('/')
624	        .chars()
625	        .take_while(|c| c.is_ascii_alphanumeric())
626	        .collect::<String>()
627	        .to_ascii_lowercase();
628	
629	    match name.as_str() {
630	        "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
631	            if is_close {
632	                "\n\n".to_string()
633	            } else {
634	                let level = name[1..].parse::<usize>().unwrap_or(1);
635	                format!("\n{} ", "#".repeat(level))
636	            }
637	        }
638	        "br" => "\n".to_string(),
639	        "p" | "div" => "\n".to_string(),
640	        "li" => {
641	            if is_close {
642	                "\n".to_string()
643	            } else {
644	                "- ".to_string()
645	            }
646	        }
647	        "ul" | "ol" => "\n".to_string(),
648	        "blockquote" => {
649	            if is_close {
650	                "\n".to_string()
651	            } else {
652	                "\n> ".to_string()
653	            }
654	        }
655	        "b" | "strong" => "**".to_string(),
656	        "i" | "em" => "*".to_string(),
657	        "code" => "`".to_string(),
658	        _ => String::new(),
659	    }
660	}
661	
662	/// Rewrite `<a href="URL">TEXT</a>` into `[TEXT](URL)` before generic stripping.
663	fn rewrite_anchors(html: &str) -> String {
664	    let mut out = String::with_capacity(html.len());
665	    let lower = html.to_ascii_lowercase();
666	    let mut cursor = 0usize;
667	    while let Some(rel) = lower[cursor..].find("<a ") {
668	        let start = cursor + rel;
669	        out.push_str(&html[cursor..start]);
670	        // Find end of the opening tag.
671	        let Some(open_end_rel) = html[start..].find('>') else {
672	            out.push_str(&html[start..]);
673	            return out;
674	        };
675	        let open_end = start + open_end_rel;
676	        let open_tag = &html[start..=open_end];
677	        let href = extract_attr(open_tag, "href").unwrap_or_default();
678	        // Find the matching close.
679	        let Some(close_rel) = lower[open_end..].find("</a>") else {
680	            out.push_str(&html[start..]);
681	            return out;
682	        };
683	        let close = open_end + close_rel;
684	        let text = &html[open_end + 1..close];
685	        if href.is_empty() {
686	            out.push_str(text);
687	        } else {
688	            out.push_str(&format!("[{}]({})", text.trim(), href));
689	        }
690	        cursor = close + "</a>".len();
691	    }
692	    out.push_str(&html[cursor..]);
693	    out
694	}
695	
696	/// Pull a quoted attribute value out of an opening tag.
697	fn extract_attr(tag: &str, attr: &str) -> Option<String> {
698	    let lower = tag.to_ascii_lowercase();
699	    let key = format!("{}=", attr);
700	    let key_at = lower.find(&key)?;
701	    let after = &tag[key_at + key.len()..];
702	    let after = after.trim_start();
703	    let quote = after.chars().next()?;
704	    if quote == '"' || quote == '\'' {
705	        let rest = &after[1..];
706	        let end = rest.find(quote)?;
707	        Some(rest[..end].to_string())
708	    } else {
709	        Some(after.split_whitespace().next().unwrap_or("").to_string())
710	    }
711	}
712	
713	/// Remove whole `<tag>…</tag>` blocks (case-insensitive) for the given tag names.
714	fn strip_blocks(html: &str, tags: &[&str]) -> String {
715	    let mut result = html.to_string();
716	    for tag in tags {
717	        let lower = result.to_ascii_lowercase();
718	        let open = format!("<{}", tag);
719	        let close = format!("</{}>", tag);
720	        let mut out = String::with_capacity(result.len());
721	        let mut cursor = 0usize;
722	        let lower_ref = lower.as_str();
723	        while let Some(rel) = lower_ref[cursor..].find(&open) {
724	            let start = cursor + rel;
725	            out.push_str(&result[cursor..start]);
726	            if let Some(close_rel) = lower_ref[start..].find(&close) {
727	                cursor = start + close_rel + close.len();
728	            } else {
729	                cursor = result.len();
730	            }
731	        }
732	        out.push_str(&result[cursor..]);
733	        result = out;
734	    }
735	    result
736	}
737	
738	/// Decode the handful of HTML entities Apple Notes emits.
739	fn decode_entities(input: &str) -> String {
740	    let mut out = String::with_capacity(input.len());
741	    let mut rest = input;
742	    while let Some(idx) = rest.find('&') {
743	        out.push_str(&rest[..idx]);
744	        let tail = &rest[idx..];
745	        if let Some(semi) = tail.find(';').filter(|semi| *semi <= 10) {
746	            let entity = &tail[1..semi];
747	            let decoded = match entity {
748	                "amp" => Some('&'),
749	                "lt" => Some('<'),
750	                "gt" => Some('>'),
751	                "quot" => Some('"'),
752	                "apos" | "#39" => Some('\''),
753	                "nbsp" => Some(' '),
754	                _ => decode_numeric_entity(entity),
755	            };
756	            if let Some(ch) = decoded {
757	                out.push(ch);
758	                rest = &tail[semi + 1..];
759	                continue;
760	            }
761	        }
762	        out.push('&');
763	        rest = &tail[1..];
764	    }
765	    out.push_str(rest);
766	    out
767	}
768	
769	fn decode_numeric_entity(entity: &str) -> Option<char> {
770	    let code = if let Some(hex) = entity
771	        .strip_prefix("#x")
772	        .or_else(|| entity.strip_prefix("#X"))
773	    {
774	        u32::from_str_radix(hex, 16).ok()?
775	    } else if let Some(dec) = entity.strip_prefix('#') {
776	        dec.parse::<u32>().ok()?
777	    } else {
778	        return None;
779	    };
780	    char::from_u32(code)
781	}
782	
783	/// Trim trailing spaces and collapse runs of blank lines down to one.
784	fn collapse_whitespace(input: &str) -> String {
785	    let mut lines: Vec<String> = input
786	        .replace('\r', "")
787	        .split('\n')
788	        .map(|line| line.trim_end().to_string())
789	        .collect();
790	    // Collapse 2+ consecutive blank lines into a single blank line.
791	    let mut collapsed: Vec<String> = Vec::with_capacity(lines.len());
792	    let mut blank_run = false;
793	    for line in lines.drain(..) {
794	        if line.is_empty() {
795	            if !blank_run {
796	                collapsed.push(line);
797	            }
798	            blank_run = true;
799	        } else {
800	            collapsed.push(line);
801	            blank_run = false;
802	        }
803	    }
804	    collapsed.join("\n").trim().to_string()
805	}
806	
807	#[cfg(test)]
808	mod tests {
809	    use super::*;
810	
811	    #[test]
812	    fn parses_epoch_seconds_and_millis() {
813	        assert_eq!(parse_date_value("1700000000"), Some(1_700_000_000_000));
814	        assert_eq!(parse_date_value("1700000000000"), Some(1_700_000_000_000));
815	    }
816	
817	    #[test]
818	    fn parses_rfc3339_and_date_only() {
819	        assert_eq!(
820	            parse_date_value("2023-11-14T22:13:20Z"),
821	            Some(1_700_000_000_000)
822	        );
823	        // Date-only resolves to UTC midnight.
824	        assert_eq!(parse_date_value("2021-01-01"), Some(1_609_459_200_000));
825	    }
826	
827	    #[test]
828	    fn front_matter_split_extracts_date_and_strips_block() {
829	        let raw = "---\ntitle: Hello\ncreated: 2021-01-01\n---\n\n# Hello\n\nBody text";
830	        let (date, body) = split_front_matter(raw);
831	        assert_eq!(date, Some(1_609_459_200_000));
832	        assert_eq!(body, "# Hello\n\nBody text");
833	    }
834	
835	    #[test]
836	    fn lone_triple_dash_is_kept_as_body() {
837	        let raw = "--- not front matter\nstill body";
838	        let (date, body) = split_front_matter(raw);
839	        assert_eq!(date, None);
840	        assert_eq!(body, raw);
841	    }
842	
843	    #[test]
844	    fn html_converts_headings_breaks_and_emphasis() {
845	        let html = "<h1>Title</h1><p>Hello <b>bold</b> and <i>italic</i></p><br>line2";
846	        let md = html_to_markdown(html);
847	        assert!(md.starts_with("# Title"));
848	        assert!(md.contains("**bold**"));
849	        assert!(md.contains("*italic*"));
850	        assert!(md.contains("line2"));
851	    }
852	
853	    #[test]
854	    fn html_rewrites_links_and_decodes_entities() {
855	        let html = r#"<p>See <a href="https://x.test">site</a> &amp; more</p>"#;
856	        let md = html_to_markdown(html);
857	        assert!(md.contains("[site](https://x.test)"));
858	        assert!(md.contains("& more"));
859	    }
860	
861	    #[test]
862	    fn sanitize_segment_strips_separators_and_dots() {
863	        assert_eq!(sanitize_segment("a/b:c"), "a b c");
864	        assert_eq!(sanitize_segment("  .. "), "");
865	        assert_eq!(sanitize_segment("Work Notes"), "Work Notes");
866	    }
867	}
